"""Pydantic v2 bindings, bundled schemas and the validation runtime for one Python package."""

from __future__ import annotations

import json
import subprocess
import sys
import tempfile
import tomllib
import warnings
from pathlib import Path
from typing import Any

from .sources import Contract, bundled, closure, header

TEMPLATES = Path(__file__).parent / "templates"
PACKAGE_HEADER = (
    "# GENERATED by `python -m jana_tools codegen` from scripts/jana_tools/codegen/templates/{name}\n"
    "# Do not edit: change the template and regenerate (ARC-30).\n"
)


VERSIONS = Path(__file__).parent / "versions.toml"


def _open_enum_paths(defs: dict[str, Any], node: Any, path: list[str], opens: set[str]) -> list[tuple[list[str], str]]:
    """Where an event's fields use an open enum (`x-open-enum`, API-35): field paths, `*` for any array item."""
    found: list[tuple[list[str], str]] = []
    if not isinstance(node, dict):
        return found
    ref = str(node.get("$ref", "")).rsplit("/", 1)[-1]
    if ref in opens:
        return [(path, ref)]
    if ref and not ref.startswith("ev_") and ref in defs:
        found += _open_enum_paths(defs, defs[ref], path, opens)
    for key, child in node.get("properties", {}).items():
        found += _open_enum_paths(defs, child, [*path, key], opens)
    for keyword in ("anyOf", "oneOf", "allOf"):
        for child in node.get(keyword, []):
            found += _open_enum_paths(defs, child, path, opens)
    if isinstance(node.get("items"), dict):
        found += _open_enum_paths(defs, node["items"], [*path, "*"], opens)
    return found


def compat_data(contracts: list[Contract]) -> dict[str, Any]:
    """The interface version table and, for the tolerant reader (API-35), the known envelope fields, the fields of
    each event type, and where each event type uses an open enum with the values this build knows."""
    contract = next(c for c in contracts if c.stem == "api/events")
    events = contract.schema
    defs = events["$defs"]
    opens = set(contract.open_enums)
    types = {}
    open_fields: dict[str, list[dict[str, Any]]] = {}
    for name, definition in defs.items():
        const = definition.get("properties", {}).get("type", {}).get("const")
        if name.startswith("ev_") and isinstance(const, str):
            types[const] = sorted(definition["properties"])
            paths = _open_enum_paths(defs, definition, [], opens)
            if paths:
                open_fields[const] = [{"path": p, "values": defs[e]["enum"]} for p, e in paths]
    return {
        "interfaces": tomllib.loads(VERSIONS.read_text())["interfaces"],
        "events": {"envelope": sorted(events["properties"]), "types": dict(sorted(types.items())),
                   "open_enums": dict(sorted(open_fields.items()))},
    }  # fmt: skip


def without_formats(node: Any) -> Any:
    """Drop `format` for model generation: dates and times stay strings in the models, exactly as on the wire,
    and the validation runtime checks the formats (the generator otherwise emits date types that cannot carry
    a `pattern` constraint)."""
    if isinstance(node, dict):
        return {
            k: (v if k in ("const", "enum", "default") else without_formats(v))
            for k, v in node.items()
            if not (k == "format" and isinstance(v, str))
        }
    if isinstance(node, list):
        return [without_formats(x) for x in node]
    return node


def _models(contract: Contract, source: Path, out: Path) -> None:
    from datamodel_code_generator import DataModelType, InputFileType, LiteralType, PythonVersion, generate
    from datamodel_code_generator.format import Formatter

    with warnings.catch_warnings():
        warnings.simplefilter("ignore")  # duplicate-field and formatter-default notices from the generator
        generate(
            source,
            input_file_type=InputFileType.JsonSchema,
            output=out,
            output_model_type=DataModelType.PydanticV2BaseModel,
            target_python_version=PythonVersion.PY_312,
            extra_fields="forbid",
            use_annotated=True,
            field_constraints=True,
            use_union_operator=True,
            use_standard_collections=True,
            enum_field_as_literal=LiteralType.All,
            collapse_root_models=False,
            use_type_alias=True,
            disable_timestamp=True,
            use_double_quotes=True,
            use_title_as_name=True,
            formatters=[Formatter.BUILTIN],
            custom_file_header=header(contract, "#").rstrip("\n"),
        )


def generate_python(
    contracts: list[Contract], out: Path, package: str, all_contracts: list[Contract] | None = None
) -> None:
    """Models for `contracts`, plus every schema they reference, into package directory `out`."""
    all_contracts = all_contracts or contracts
    referenced = closure(contracts, all_contracts)
    out.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory() as scratch:
        for contract in contracts:
            source = Path(scratch) / contract.rel
            source.parent.mkdir(parents=True, exist_ok=True)
            source.write_text(json.dumps(without_formats(bundled(contract, all_contracts)), indent=1))
            module = out / f"{contract.module}.py"
            module.parent.mkdir(parents=True, exist_ok=True)
            _models(contract, source, module)

    # Canonical schemas (prose-free, $id kept) for the validation runtime.
    for contract in referenced:
        target = out / "schemas" / contract.rel
        target.parent.mkdir(parents=True, exist_ok=True)
        schema = {"$comment": f"GENERATED from {contract.source} sha256 {contract.sha256}; do not edit"}
        schema.update(contract.schema)
        target.write_text(json.dumps(schema, indent=1, sort_keys=False) + "\n")

    if any(c.stem == "api/events" for c in referenced):
        (out / "compat.json").write_text(json.dumps(compat_data(referenced), indent=1, sort_keys=True) + "\n")
        names: tuple[str, ...] = ("_validation.py", "_compat.py", "__init__.py")
    else:
        names = ("_validation.py", "__init__.py")
    for name in names:
        text = (TEMPLATES / f"{name}.tmpl").read_text().replace("{{PACKAGE}}", package)
        (out / name).write_text(PACKAGE_HEADER.format(name=f"{name}.tmpl") + text)
    for directory in sorted({p.parent for p in out.rglob("*.py")} - {out}):
        dotted = f"{package}.{directory.relative_to(out).as_posix().replace('/', '.')}"
        (directory / "__init__.py").write_text(PACKAGE_HEADER.format(name="__init__.py.tmpl") + f'"""{dotted}"""\n')

    subprocess.run([sys.executable, "-m", "ruff", "format", "--quiet", str(out)], check=True)
    subprocess.run(
        [sys.executable, "-m", "ruff", "check", "--quiet", "--fix", "--select", "I,F401", str(out)], check=False
    )
